import {
	Accessor,
	Component,
	createContext,
	createEffect,
	createSignal,
	For,
	onCleanup,
	Setter,
	Show,
	useContext,
} from "solid-js";
import { modifyMutable, reconcile } from "solid-js/store";
import { render } from "solid-js/web";

import { RadioButton } from "#core/ui-next/components/radio-button.jsx";
import { Tab } from "#core/ui-next/components/tab.jsx";
import { IModelProxy, ObjectEditor } from "#core/ui-next/debug/object-editor.jsx";
import { ObjectHistory } from "#core/ui-next/debug/object-history.jsx";
import { SimpleButton } from "#core/ui-next/debug/simple-button.jsx";
import { createArraySignal, Mutator } from "#core/ui-next/utilities/solid-utilities.js";

class MutableProxy implements IModelProxy {
	constructor(
		public name: string,
		public id: number,
		private mutable: object,
	) {}

	public set value(value: object) {
		modifyMutable(this.mutable, reconcile(value));
	}

	public get value() {
		return this.mutable;
	}
}

class StoreProxy implements IModelProxy {
	constructor(
		public name: string,
		public id: number,
		private accessor: Accessor<object>,
		private setter: Setter<object>,
	) {}

	public set value(value: object) {
		this.setter((_) => value);
	}

	public get value() {
		return this.accessor();
	}
}

let currentId = 1;

class DebugContextProvider {
	private _registeredModels: Accessor<IModelProxy[]>;
	private _mutateModels: Mutator<IModelProxy[]>;

	public get models(): Accessor<IModelProxy[]> {
		return this._registeredModels;
	}

	constructor() {
		const [registeredModels, mutateModels] = createArraySignal<IModelProxy>();
		this._registeredModels = registeredModels;
		this._mutateModels = mutateModels;
	}

	public registerMutableModel(name: string, model: object) {
		this.registerProxy(new MutableProxy(name, currentId++, model));
	}

	public registerStoreModel(name: string, modelGetter: Accessor<object>, modelSetter: Setter<object>) {
		this.registerProxy(new StoreProxy(name, currentId++, modelGetter, modelSetter));
	}

	private registerProxy(proxy: IModelProxy) {
		this._mutateModels((m) => m.push(proxy));

		onCleanup(() => {
			this._mutateModels((models) => {
				const foundModel = models.findIndex((m) => m.id == proxy.id);
				if (foundModel >= 0) {
					models.splice(foundModel, 1);
				}
			});
		});
	}
}

export const DebugContext = createContext(new DebugContextProvider());

export const DebugPanel: Component = () => {
	const [isOpen, setIsOpen] = createSignal(false);
	const [isRight, setIsRight] = createSignal(true);
	const [activeProxy, setActiveProxy] = createSignal<IModelProxy>();

	const debugContext = useContext(DebugContext);

	// Clear active proxy if it is no longer registered
	createEffect(() => {
		const proxy = activeProxy();
		if (proxy && !debugContext.models().find((p) => p.id == proxy.id)) {
			setActiveProxy(undefined);
		}
	});

	function movePanel(moveRight: boolean) {
		if (moveRight == isRight()) {
			setIsOpen(false);
		} else {
			setIsRight((r) => !r);
		}
	}

	return (
		<Show
			when={isOpen()}
			fallback={
				<SimpleButton
					class={`absolute bottom-0 ${isRight() ? "right-0" : "left-0"}`}
					onActivate={() => setIsOpen(true)}
				>
					{isRight() ? "<<" : ">>"}
				</SimpleButton>
			}
		>
			<Tab
				class={`absolute top-0 bottom-0 w-1\\/2 ${isRight() ? "right-0" : "left-0"}`}
				style={{ "background-color": "#222A" }}
			>
				<div class={`flex flex-col inset-0 absolute`}>
					<div class="flex flex-row">
						<SimpleButton onActivate={() => movePanel(false)}>&lt;&lt;</SimpleButton>
						<div class="flex-auto" />
						<Tab.TabList />
						<div class="flex-auto" />
						<SimpleButton onActivate={() => movePanel(true)}>&gt;&gt;</SimpleButton>
					</div>
					<div class="flex flex-row flex-auto">
						<div>Models</div>
						<div class="flex flex-col border border-accent-1 p-2">
							<For each={debugContext.models()}>
								{(model: IModelProxy) => (
									<RadioButton
										isChecked={activeProxy() == model}
										onActivate={() => setActiveProxy(model)}
									>
										{model.name}-{model.id}
									</RadioButton>
								)}
							</For>
						</div>
						<Tab.Output />
					</div>
				</div>

				<Tab.Item
					name="History"
					title={() => "History"}
					body={() => (
						<ObjectHistory
							class="flex-auto"
							proxy={activeProxy()}
						/>
					)}
				/>

				<Tab.Item
					name="Edit"
					title={() => "Edit"}
					body={() => (
						<ObjectEditor
							class="flex-auto"
							proxy={activeProxy()}
						/>
					)}
				/>
			</Tab>
		</Show>
	);
};

export function showDebugPanel() {
	render(() => <DebugPanel />, document.body);
}
